// Browser decompression keeps the deployable Godot asset below the host's file limit.
(()=>{const original=window.fetch.bind(window);window.fetch=async(input,options)=>{const url=new URL(input instanceof Request?input.url:String(input),location.href);if(url.origin===location.origin&&url.pathname.endsWith('/engine.wasm')){if(typeof DecompressionStream==='undefined')throw new Error('请使用新版浏览器，或返回轻量知识图谱。');const response=await original(new URL('engine.wasm.gz',url),options);if(!response.ok)throw new Error('Godot 引擎下载失败：'+response.status);return new Response(response.body.pipeThrough(new DecompressionStream('gzip')),{headers:{'Content-Type':'application/wasm','Content-Length':'43699190'}});}return original(input,options);};})();
